  # Defines the Intercom SDK type.
  class Intercom
    attr_reader :admins, :macros, :office_hours, :ai_content, :articles, :away_status_reasons,
                :audiences, :reporting_data_export, :fin_agent, :help_center, :internal_articles,
                :folders, :ip_allowlist, :companies, :notes, :contacts, :subscription_types, :tags,
                :banners, :content, :content_snippets, :dynamic_content, :conversations,
                :conversations_attributes, :custom_object_instances, :data_attributes,
                :data_connectors, :data_events, :data_export, :jobs, :messages, :news, :segments,
                :switch, :calls, :teams, :ticket_states, :ticket_type_attributes, :ticket_types,
                :tickets, :visitors, :brands, :emails, :workflows

    SUB_NAMESPACES = {
      admins: AdminsNamespace,
      macros: MacrosNamespace,
      office_hours: OfficeHoursNamespace,
      ai_content: AiContentNamespace,
      articles: ArticlesNamespace,
      away_status_reasons: AwayStatusReasonsNamespace,
      audiences: AudiencesNamespace,
      reporting_data_export: ReportingDataExportNamespace,
      fin_agent: FinAgentNamespace,
      help_center: HelpCenterNamespace,
      internal_articles: InternalArticlesNamespace,
      folders: FoldersNamespace,
      ip_allowlist: IpAllowlistNamespace,
      companies: CompaniesNamespace,
      notes: NotesNamespace,
      contacts: ContactsNamespace,
      subscription_types: SubscriptionTypesNamespace,
      tags: TagsNamespace,
      banners: BannersNamespace,
      content: ContentNamespace,
      content_snippets: ContentSnippetsNamespace,
      dynamic_content: DynamicContentNamespace,
      conversations: ConversationsNamespace,
      conversations_attributes: ConversationsAttributesNamespace,
      custom_object_instances: CustomObjectInstancesNamespace,
      data_attributes: DataAttributesNamespace,
      data_connectors: DataConnectorsNamespace,
      data_events: DataEventsNamespace,
      data_export: DataExportNamespace,
      jobs: JobsNamespace,
      messages: MessagesNamespace,
      news: NewsNamespace,
      segments: SegmentsNamespace,
      switch: SwitchNamespace,
      calls: CallsNamespace,
      teams: TeamsNamespace,
      ticket_states: TicketStatesNamespace,
      ticket_type_attributes: TicketTypeAttributesNamespace,
      ticket_types: TicketTypesNamespace,
      tickets: TicketsNamespace,
      visitors: VisitorsNamespace,
      brands: BrandsNamespace,
      emails: EmailsNamespace,
      workflows: WorkflowsNamespace
    }.freeze
    private_constant :SUB_NAMESPACES

    def initialize(config)
      @config = config
      SUB_NAMESPACES.each do |accessor, namespace|
        instance_variable_set(:"@#{accessor}", namespace.new(config))
      end
    end

    # Turns SDK logging on and configures it. Logging is OFF by default — this
    # SDK reports nothing until you call this (or construct the client with a
    # config whose logging is enabled). Reports go to the endpoint this build was
    # generated with, or to the endpoint you pass; with neither, nothing is sent.
    # Pass enabled: false to turn logging back off.
    def set_logging_config(**fields)
      logging = (@config.logging ||= LoggingConfig.new)
      # Opting in IS the point of this call, so enabled flips to true — the
      # keyword loop below runs after, so an explicit enabled: false wins.
      logging.enabled = true
      fields.each do |key, value|
        setter = :"#{key}="
        raise ArgumentError, "LoggingConfig has no field #{key}" unless logging.respond_to?(setter)

        logging.public_send(setter, value)
      end
      logging
    end
  end
end
